        'uploaded_at': model.uploaded_at.isoformat(),
        'production_status': model.production_status
    } for model in models])

@app.route('/models', methods=['POST'])
@login_required
def upload_model():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400
    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400
    if file and file.filename.endswith('.zip'):
        file_path = os.path.join('uploads', file.filename)
        file.save(file_path)
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall('uploads')
        model_name = request.form.get('name')
        model_version = request.form.get('version')
        model_code = ''
        model_file = None
        for root, dirs, files in os.walk('uploads'):
            for file in files:
                if file.endswith('.py'):
                    model_file = os.path.join(root, file)
                    break
        if not model_file:
            return jsonify({'error': 'No model file found in the zip'}), 400
        with open(model_file, 'r') as f:
            model_code = f.read()
        model = Model(name=model_name, version=model_version, uploaded_by=current_user.id, code=model_code)
        db.session.add(model)
        db.session.commit()
        os.remove(file_path)
        return jsonify({'message': 'Model uploaded successfully', 'model_id': model.id})
    else:
        return jsonify({'error': 'Invalid file format'}), 400

@app.route('/models/<int:model_id>/test', methods=['POST'])
@login_required
