    model = Model.query.get(model_id)
    if not model:
        return jsonify({'error': 'Model not found'}), 404
    test_name = request.form.get('test_name')
    test_code = request.form.get('test_code')
    if not test_code:
        return jsonify({'error': 'Test code is required'}), 400
    try:
        # Create a temporary directory to store the test code
        test_dir = os.path.join('tests', f'test_{model_id}_{uuid.uuid4()}')
        os.makedirs(test_dir, exist_ok=True)
        test_file = os.path.join(test_dir, 'test.py')
        with open(test_file, 'w') as f:
            f.write(test_code)
        # Run the test
        result = subprocess.run(['python', test_file], capture_output=True, text=True)
        test_result = {
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        }
        # Store the test result
        test_result_db = TestResult(model_id=model_id, test_name=test_name, test_result=json.dumps(test_result))
        db.session.add(test_result_db)
        db.session.commit()
        return jsonify({'message': 'Test completed', 'test_result': test_result})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/models/<int:model_id>/deploy', methods=['POST'])
