@app.route('/models/<int:model_id>/rollback', methods=['POST'])
@login_required
def rollback_model(model_id):
    model = Model.query.get(model_id)
    if not model:
        return jsonify({'error': 'Model not found'}), 404
    # Get the latest version of the model
    latest_version = ModelVersion.query.filter_by(model_id=model_id).order_by(ModelVersion.id.desc()).first()
    if not latest_version:
        return jsonify({'error': 'No versions found for the model'}), 404
    # Create a new version of the model with the latest version's code
