    code = db.Column(db.Text, nullable=False)
    test_results = db.Column(db.Text, nullable=True)
    production_status = db.Column(db.Boolean, default=False)

# Model for tracking model versions and rollbacks
class ModelVersion(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    model_id = db.Column(db.Integer, db.ForeignKey('model.id'), nullable=False)
    version = db.Column(db.String(20), nullable=False)
    code = db.Column(db.Text, nullable=False)
    uploaded_at = db.Column(db.DateTime, default=datetime.datetime.utcnow)

# Model for tracking test results
class TestResult(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    model_id = db.Column(db.Integer, db.ForeignKey('model.id'), nullable=False)
    test_name = db.Column(db.String(100), nullable=False)
    test_result = db.Column(db.Text, nullable=False)
    test_time = db.Column(db.DateTime, default=datetime.datetime.utcnow)

