@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')
    user = User.query.filter_by(username=username).first()
    if user and user.check_password(password):
        login_user(user)
        return jsonify({'message': 'Logged in successfully'})
    else:
        return jsonify({'error': 'Invalid username or password'}), 401

@app.route('/logout', methods=['POST'])
@login_required
def logout():
    logout_user()
    return jsonify({'message': 'Logged out successfully'})

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')
    role = data.get('role', 'user')
    if User.query.filter_by(username=username).first():
        return jsonify({'error': 'Username already exists'}), 400
    user = User(username=username)
    user.set_password(password)
    user.role = role
    db.session.add(user)
    db.session.commit()
    return jsonify({'message': 'User registered successfully'})

@app.route('/models', methods=['GET'])
@login_required
def list_models():
    models = Model.query.all()
    return jsonify([{
        'id': model.id,
        'name': model.name,
        'version': model.version,
        'uploaded_by': model.uploaded_by,
        'uploaded_at': model.uploaded_at.isoformat(),
        'production_status': model.production_status
    } for model in models])

@app.route('/models', methods=['POST'])
@login_required
def upload_model():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400
    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400
    if file and file.filename.endswith('.zip'):
        file_path = os.path.join('uploads', file.filename)
        file.save(file_path)
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall('uploads')
        model_name = request.form.get('name')
        model_version = request.form.get('version')
        model_code = ''
        model_file = None
        for root, dirs, files in os.walk('uploads'):
            for file in files:
                if file.endswith('.py'):
                    model_file = os.path.join(root, file)
                    break
        if not model_file:
            return jsonify({'error': 'No model file found in the zip'}), 400
        with open(model_file, 'r') as f:
            model_code = f.read()
        model = Model(name=model_name, version=model_version, uploaded_by=current_user.id, code=model_code)
        db.session.add(model)
        db.session.commit()
        os.remove(file_path)
        return jsonify({'message': 'Model uploaded successfully', 'model_id': model.id})
    else:
        return jsonify({'error': 'Invalid file format'}), 400

@app.route('/models/<int:model_id>/test', methods=['POST'])
@login_required
def test_model(model_id):
    model = Model.query.get(model_id)
    if not model:
        return jsonify({'error': 'Model not found'}), 404
    test_name = request.form.get('test_name')
    test_code = request.form.get('test_code')
    if not test_code:
        return jsonify({'error': 'Test code is required'}), 400
    try:
        # Create a temporary directory to store the test code
        test_dir = os.path.join('tests', f'test_{model_id}_{uuid.uuid4()}')
        os.makedirs(test_dir, exist_ok=True)
        test_file = os.path.join(test_dir, 'test.py')
        with open(test_file, 'w') as f:
            f.write(test_code)
        # Run the test
        result = subprocess.run(['python', test_file], capture_output=True, text=True)
        test_result = {
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        }
        # Store the test result
        test_result_db = TestResult(model_id=model_id, test_name=test_name, test_result=json.dumps(test_result))
        db.session.add(test_result_db)
        db.session.commit()
        return jsonify({'message': 'Test completed', 'test_result': test_result})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/models/<int:model_id>/deploy', methods=['POST'])
@login_required
def deploy_model(model_id):
    model = Model.query.get(model_id)
    if not model:
        return jsonify({'error': 'Model not found'}), 404
    model.production_status = True
    db.session.commit()
    return jsonify({'message': 'Model deployed successfully'})

@app.route('/models/<int:model_id>/rollback', methods=['POST'])
@login_required
def rollback_model(model_id):
    model = Model.query.get(model_id)
    if not model:
        return jsonify({'error': 'Model not found'}), 404
    # Get the latest version of the model
    latest_version = ModelVersion.query.filter_by(model_id=model_id).order_by(ModelVersion.id.desc()).first()
    if not latest_version:
        return jsonify({'error': 'No versions found for the model'}), 404
    # Create a new version of the model with the latest version's code
    new_version = ModelVersion(
        model_id=model_id,
        version=latest_version.version,
        code=latest_version.code
    )
    db.session.add(new_version)
    db.session.commit()
    # Update the model's code to the latest version's code
    model.code = latest_version.code
    model.version = latest_version.version
    db.session.commit()
    return jsonify({'message': 'Model rolled back to latest version'})

if __name__ == '__main__':
    app.run(debug=True)

