def parse_microformats(html):
    soup = BeautifulSoup(html, 'html.parser')
    microformats = []
    for tag in soup.find_all():
        class_name = tag.get('class')
        if class_name and re.search(r'\b(h-[^ ]+)', ' '.join(class_name)):
